];

// SCORECARD (fill after each problem):
const problem_scorecard = {
    problemId: 0,
    archetype: '',
    insightStatement: '',  // THE MOST IMPORTANT FIELD
    criteria: {
        pattern:        0,  // Correct archetype within 5 minutes
        code:           0,  // Working optimal (or brute force with O(?) stated)
        tests:          0,  // Provided examples + edge case
        complexity:     0,  // Time AND space unprompted
        communication:  0,  // No > 90s silence; full 8-step framework
    },
    timeUsed: 0,
    stressTestPassed: false,
};

// STRESS TEST HELPER:
function stressTest(efficient, brute, generator, trials=200) {
    for (let t=0; t<trials; t++) {
        const input = generator();
        const a = efficient(...input);
        const b = brute(...input);
        if (a !== b) {
            console.error('FAILED:', JSON.stringify(input), '\nEfficient:', a, '\nBrute:', b);
            return false;
        }
    }
    return true;
}
console.log('Capstone problem categories:', capstoneHardProblems.length);

// SYSTEM DESIGN WITH DSA LAYER — CAPSTONE FORMAT

// Choose ONE of these three system design questions:
const capstoneSysDesignQuestions = [
    {
        question: 'Design a URL Shortener (bit.ly)',
        scale: '1 billion URLs, 100M daily redirects, 10M daily creates',
        dsaRequirements: [
            { component: 'URL mapping store',   required_ds: 'Hash index on short code (O(1) redirect)' },
            { component: 'Redirect cache',       required_ds: 'LRU cache (HashMap+DLL, O(1) get/put)' },
            { component: 'Cache distribution',   required_ds: 'Consistent hashing (O(K/N) remapping)' },
            { component: 'Analytics counter',    required_ds: 'Fenwick tree or approximate counter' },
            { component: 'Short code collision', required_ds: 'Bloom filter (check existence before DB)' },
        ]
    },
    {
        question: 'Design Twitter Feed',
        scale: '300M users, 500M tweets/day, fanout-on-write vs fanout-on-read',
        dsaRequirements: [
            { component: 'Tweet storage',        required_ds: 'B+ tree index on (user_id, timestamp)' },
            { component: 'Feed cache',           required_ds: 'LRU per user (evict stale feeds)' },
            { component: 'Trending topics',      required_ds: 'Count-Min Sketch or top-K heap' },
            { component: 'User shard routing',   required_ds: 'Consistent hashing (user_id -> shard)' },
