            { component: 'Expired counter cleanup', required_ds: 'Min-heap of (expiry_time, key)' },
            { component: 'Hot key detection',    required_ds: 'Count-Min Sketch (probabilistic frequency)' },
        ]
    },
];

// DSA JUSTIFICATION TABLE FORMAT (fill for every component):
const justificationTemplate = {
    component: '',
    chosenDS: '',
    dominantOperation: '',        // e.g. 'O(1) exact-match lookup'
    complexity: { time: '', space: '' },
    tradeoff: '',                 // e.g. 'no range queries; use B+ tree if range needed'
    atScale: '',                  // e.g. 'consistent hashing when adding node 9 -> 11% remapping'
};

console.log('System design questions available:', capstoneSysDesignQuestions.length);

// PEER CODE REVIEW FRAMEWORK

// CODE REVIEW CHECKLIST:
const reviewChecklist = [
    {
        category: 'Correctness',
        questions: [
            'Does this produce correct output for the provided examples?',
            'Does this handle empty input?',
            'Does this handle single-element input?',
            'Are there any off-by-one errors in loop bounds?',
            'Are any integer overflow conditions possible?',
        ]
    },
    {
        category: 'Complexity',
        questions: [
            'Is the time complexity stated? Is it correct?',
            'Is the space complexity stated? Is auxiliary space counted?',
            'Could the time complexity be improved with a different data structure?',
            'Are there any hidden O(n) operations inside an outer loop (making it O(n^2))?',
        ]
    },
    {
        category: 'Algorithm Choice',
        questions: [
            'Is this the right data structure for the dominant operation?',
            'Is the choice justified in a comment?',
            'Is there a simpler approach with the same complexity?',
        ]
    },
    {
        category: 'Style and Readability',
        questions: [
            'Are variable names descriptive (left/right vs l/r for non-trivial code)?',
            'Are helper functions used for repeated logic?',
            'Are magic numbers explained (why 4*n for segment tree size)?',
            'Is the code self-explanatory or does it need comments to explain non-obvious decisions?',
        ]
    },
    {
        category: 'Edge Cases',
        questions: [
            'What happens with n=0 (empty input)?',
            'What happens with n=1?',
            'What happens with all-same elements?',
            'What happens with the maximum allowed input size?',
        ]
    },
];

// EXAMPLE CODE TO REVIEW:
// Below is a LRU cache implementation with intentional issues for review practice
const codeToReview = `
class LRUCache {
    constructor(c) {  // Issue 1: non-descriptive parameter name
        this.cap = c;
        this.m = new Map();
        // Issue 2: No documentation of the sentinel node pattern
        this.h = {k:null,v:null,p:null,n:null}; // Issue 3: p/n vs prev/next
        this.t = {k:null,v:null,p:null,n:null};
        this.h.n = this.t;
        this.t.p = this.h;
    }
    // Issue 4: No time complexity comment
    get(key) {
        if (!this.m.has(key)) return -1;
        const node = this.m.get(key);
        this.remove(node);
        this.add(node);
        return node.v;
    }
    // Issue 5: missing put() method entirely -> would fail tests
}
`;
console.log('Review categories:', reviewChecklist.length);

