// AUDIT RESULTS TABLE:
const auditTable = auditCategories.map(cat => ({
    ...cat,
    problems: [
        { id: null, difficulty: null, timeTaken: null, passed: null },
        { id: null, difficulty: null, timeTaken: null, passed: null },
        { id: null, difficulty: null, timeTaken: null, passed: null },
    ],
    categoryPass: false, // true if all 3 problems pass within target time
}));

// PASS CRITERION:
function isProblemPass(problem, targetTime) {
    return problem.timeTaken <= targetTime[problem.difficulty] &&
           problem.passed === true;
}

function isCategoryPass(auditEntry) {
    return auditEntry.problems.every(p =>
        isProblemPass(p, auditEntry.targetTime));
}

function isFullAuditPass(auditTable) {
    return auditTable.every(isCategoryPass);
}

console.log('Audit categories:', auditCategories.length);
console.log('Total problems:', auditCategories.length * 3);

